INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10001, 1, "ふっふっふ、これでカヤぴぃとボスを見返してやるです！", 2, "vo_minigame_1004_top_1_000", "vo_minigame_1004", 1000101);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10002, 1, "しりとりでの戦い、お兄さんにも手伝ってもらうです", 2, "vo_minigame_1004_top_1_003", "vo_minigame_1004", 1000201);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10003, 2, "どんなケンカも売られた以上は買うのが喧嘩屋だ！やってやるぜ！", 1, "vo_minigame_1004_top_1_004", "vo_minigame_1004", 1000301);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10004, 2, "石板でしりとりか……イノリのヤツおもしろいこと考えるな", 1, "vo_minigame_1004_top_1_005", "vo_minigame_1004", 1000401);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10005, 2, "しりとりだろうがなんだろうが返り討ちにしてやるぜ", 1, "vo_minigame_1004_top_1_006", "vo_minigame_1004", 1000501);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10006, 3, "ぐもも……（オデ、ハラヘッタ）", 2, "vo_minigame_1004_top_1_007", "vo_minigame_1004", 1000601);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10007, 3, "ぐもももも（シリトリ タノシイ）", 2, "vo_minigame_1004_top_1_008", "vo_minigame_1004", 1000701);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10008, 3, "ぐもももも！（イノリ イイヤツ）", 2, "vo_minigame_1004_top_1_009", "vo_minigame_1004", 1000801);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10009, 1, "カヤぴぃ相手でも手加減しないです", 2, "vo_minigame_1004_top_2_010", "vo_minigame_1004", 1000901);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10009, 2, "上等だ！やるからには本気で来いよな", 1, "vo_minigame_1004_top_2_011", "vo_minigame_1004", 1000902);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10010, 1, "カヤぴぃ、謝るなら今のうちです", 2, "vo_minigame_1004_top_2_012", "vo_minigame_1004", 1001001);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10010, 2, "イノリこそ泣きを入れるなら今のうちだぜ？", 1, "vo_minigame_1004_top_2_013", "vo_minigame_1004", 1001002);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10011, 1, "カヤぴぃ、これからは知性の時代ですよ？", 2, "vo_minigame_1004_top_2_014", "vo_minigame_1004", 1001101);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10011, 2, "待て！オレがバカみたいにいうな！！", 1, "vo_minigame_1004_top_2_015", "vo_minigame_1004", 1001102);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10012, 1, "さあ、あたしたちの力を見せてやるです", 1, "vo_minigame_1004_top_2_016", "vo_minigame_1004", 1001201);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10012, 3, "ぐも！（マカセロ！）", 2, "vo_minigame_1004_top_2_017", "vo_minigame_1004", 1001202);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10013, 1, "よしよし、いいですようまくできたらチョコをあげるです！", 1, "vo_minigame_1004_top_2_018", "vo_minigame_1004", 1001301);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10013, 3, "ぐも！（オデ チョコスキ）", 2, "vo_minigame_1004_top_2_019", "vo_minigame_1004", 1001302);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10014, 2, "なあイノリ……もしかして当初の目的見失ってないよな？", 1, "vo_minigame_1004_top_2_023", "vo_minigame_1004", 1001401);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10014, 1, "もちろん覚えてるですカヤぴぃを倒し我々の知能を証明するです", 2, "vo_minigame_1004_top_2_024", "vo_minigame_1004", 1001402);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10015, 2, "いくらイノリ相手でも勝ちを譲る気はないからな！", 1, "vo_minigame_1004_top_2_025", "vo_minigame_1004", 1001501);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10015, 1, "望むところです手加減はなしですよ", 2, "vo_minigame_1004_top_2_026", "vo_minigame_1004", 1001502);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10016, 2, "へっ、なかなかやるじゃねえか", 1, "vo_minigame_1004_top_2_027", "vo_minigame_1004", 1001601);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10016, 1, "カヤぴぃも思ったよりやるですね！", 2, "vo_minigame_1004_top_2_028", "vo_minigame_1004", 1001602);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10017, 2, "お～い、ドラゴンもどき？", 1, "vo_minigame_1004_top_2_029", "vo_minigame_1004", 1001701);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10017, 3, "ぐもっ！？（ヒッ！）", 2, "vo_minigame_1004_top_2_030", "vo_minigame_1004", 1001702);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10018, 2, "いやあ、あんときは悪かったなはっはっは", 1, "vo_minigame_1004_top_2_031", "vo_minigame_1004", 1001801);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10018, 3, "ぐももも……（かやピィ コワカッタ）", 2, "vo_minigame_1004_top_2_032", "vo_minigame_1004", 1001802);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10019, 2, "お前ってさ……ほんとマヌケな顔してるよな", 1, "vo_minigame_1004_top_2_033", "vo_minigame_1004", 1001901);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10019, 3, "ぐも……（オマエガ イウカ）", 2, "vo_minigame_1004_top_2_034", "vo_minigame_1004", 1001902);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10020, 3, "ぐも……（ハラヘッタ チョコホシイ）", 2, "vo_minigame_1004_top_2_044", "vo_minigame_1004", 1002001);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10020, 2, "なんだ？眠いのか？", 1, "vo_minigame_1004_top_2_045", "vo_minigame_1004", 1002002);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10021, 3, "ぐもも（コイツ……キケン）", 2, "vo_minigame_1004_top_2_046", "vo_minigame_1004", 1002101);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10021, 2, "うん？　なんだ？オレの舎弟にでもなりたいのか？", 1, "vo_minigame_1004_top_2_047", "vo_minigame_1004", 1002102);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10022, 3, "ぐも…（かやピィノウキン）", 2, "vo_minigame_1004_top_2_048", "vo_minigame_1004", 1002201);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10022, 2, "おい、今失礼なこと考えてるだろ？", 1, "vo_minigame_1004_top_2_049", "vo_minigame_1004", 1002202);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10023, 2, "なあ、これいつまで続けるんだ？", 1, "vo_minigame_1004_top_3_058", "vo_minigame_1004", 1002301);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10023, 1, "カヤぴぃが降参するまでです！", 2, "vo_minigame_1004_top_3_059", "vo_minigame_1004", 1002302);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10023, 3, "ぐもも！（コウサンシロ！）", 2, "vo_minigame_1004_top_3_060", "vo_minigame_1004", 1002303);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10024, 3, "ぐも！（イノリ チョコホシイ）", 2, "vo_minigame_1004_top_3_065", "vo_minigame_1004", 1002401);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10024, 1, "しょうがないですね、食べ過ぎはダメですよ", 1, "vo_minigame_1004_top_3_066", "vo_minigame_1004", 1002402);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10024, 2, "土産のチョコ、そうとう気に入ったみたいだな", 1, "vo_minigame_1004_top_3_067", "vo_minigame_1004", 1002403);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10025, 3, "ぐも！（かやピィニハ マケナイ！）", 2, "vo_minigame_1004_top_3_068", "vo_minigame_1004", 1002501);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10025, 2, "お？なんだ？腹でも減ってるのか？", 1, "vo_minigame_1004_top_3_069", "vo_minigame_1004", 1002502);
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10025, 1, "……全然話が通じてないです", 2, "vo_minigame_1004_top_3_070", "vo_minigame_1004", 1002503);
